function getUniqueHistory(){const latest=new Map();history.forEach(x=>{if(x&&x.id!=null)latest.set(String(x.id),x)});return [...latest.values()]}function loadCompletedQuestionIds(){if(!authUser)return new Set();try{return new Set((JSON.parse(localStorage.getItem('dentatest_completed_question_ids')||'[]')||[]).map(String))}catch(_){return new Set()}}function saveCompletedQuestionIds(ids){if(!authUser)return;try{localStorage.setItem('dentatest_completed_question_ids',JSON.stringify([...ids]))}catch(_){} }function markTestQuestionsCompleted(ids){const done=loadCompletedQuestionIds();(ids||[]).forEach(id=>{if(id!=null)done.add(String(id))});saveCompletedQuestionIds(done)}function getCompletedTestQuestionIds(){const done=loadCompletedQuestionIds(),all=loadTestStatuses();Object.keys(all).forEach(key=>{const item=all[key];if(item&&item.status==='complete')key.split(',').forEach(id=>{if(id)done.add(String(id))})});saveCompletedQuestionIds(done);return done}function getCompletedTestQuestionCount(){return getCompletedTestQuestionIds().size}function getStats(filter){const a=history.filter(filter||(()=>true));return{total:a.length,correct:a.filter(x=>x.ok).length,rate:a.length?Math.round(a.filter(x=>x.ok).length/a.length*100):0}}
