function toggleTopicPicker(){const p=document.getElementById('topicPicker')||document.getElementById('quizTopicPicker');if(p)p.classList.toggle('open')}
async function selectSubjectTopic(index){const source=window.subjectTopicGroups||[];const g=source[index];if(!g)return;const lesson=window.qLesson&&window.qLesson.value||'';const label=document.getElementById('topicPickerLabel');if(label)label.textContent=g.label+' ('+g.count+' soru)';app.innerHTML=nav()+'<section class="card center"><p class="muted">Sorular hazırlanıyor…</p></section>';try{if(!lesson)throw new Error('Ders seçimi bulunamadı.');const pool=await fetchTopicQuestions(lesson,g.baseKey||g.key);if(!Array.isArray(pool))throw new Error('Soru verisi geçersiz.');g.questions=pool.slice(Number(g.offset||0),Number(g.offset||0)+Number(g.count||pool.length));if(!g.questions.length)throw new Error('Bu konu için soru bulunamadı.');window.qLesson={value:lesson};window.qTopic={value:g.key};startQuiz(g.questions,g.questionIds)}catch(e){app.innerHTML='<section class="card"><h2>⚠️ Sorular yüklenemedi</h2><p class="muted">'+escapeHtml(e.message)+'</p><button class="primary" onclick="renderHome()">← Geri</button></section>'}}
async function selectQuizTopic(index){const groups=window.quizTopicGroups||[];const g=groups[index];if(!g)return;const lessonEl=document.getElementById('qLesson');const lesson=lessonEl?lessonEl.value:'';const label=document.getElementById('topicPickerLabel');if(label)label.textContent=g.label+' ('+g.count+' soru)';const p=document.getElementById('quizTopicPicker');if(p)p.classList.remove('open');app.innerHTML=nav()+'<section class="card center"><p class="muted">Sorular hazırlanıyor…</p></section>';try{if(!lesson)throw new Error('Ders seçimi bulunamadı.');const pool=await fetch(API+'/questions?lesson='+encodeURIComponent(lesson)+'&topic='+encodeURIComponent(g.baseKey||g.key),{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('Sorular yüklenemedi.');return r.json()});if(!Array.isArray(pool))throw new Error('Soru verisi geçersiz.');g.questions=pool.slice(Number(g.offset||0),Number(g.offset||0)+Number(g.count||pool.length));if(!g.questions.length)throw new Error('Bu konu için soru bulunamadı.');window.qLesson={value:lesson};window.qTopic={value:g.key};startQuiz(g.questions,g.questionIds)}catch(e){app.innerHTML='<section class="card"><h2>⚠️ Sorular yüklenemedi</h2><p class="muted">'+escapeHtml(e.message)+'</p><button class="primary" onclick="renderHome()">← Geri</button></section>'}}
function buildTopicGroups(pool){const groups=[],byTopic={};pool.forEach(q=>{const t=q.question_group||q.topic||'';if(!t||t.toLocaleLowerCase('tr-TR')==='genel')return;(byTopic[t]||(byTopic[t]=[])).push(q)});Object.keys(byTopic).forEach(t=>{const arr=byTopic[t],total=arr.length;if(total<=29){groups.push({key:t,baseKey:t,label:t,count:total,offset:0,questions:arr});return}let offset=0,part=1;while(total-offset>29){groups.push({key:t+'__part'+part,baseKey:t,label:t+' '+part,count:20,offset,questions:arr.slice(offset,offset+20)});offset+=20;part++}const last=total-offset;if(last>0)groups.push({key:t+'__part'+part,baseKey:t,label:t+' '+part,count:last,offset,questions:arr.slice(offset,offset+last)})});return groups}
function buildSummaryTopicGroups(rawGroups){const merged=new Map();(rawGroups||[]).forEach(g=>{const t=String(g.question_group||g.topic||'').trim(),count=Number(g.count||0),ids=Array.isArray(g.question_ids)?g.question_ids.map(String):[];if(!t||t.toLocaleLowerCase('tr-TR')==='genel'||count<=0)return;const prev=merged.get(t)||{count:0,ids:[],lesson:g.lesson||''};prev.count+=count;prev.ids.push(...ids);if(!prev.lesson)prev.lesson=g.lesson||'';merged.set(t,prev)});const groups=[];merged.forEach((v,t)=>{const count=v.count,ids=v.ids;if(count<=29){groups.push({key:t,baseKey:t,label:t,count,offset:0,questionIds:ids,questions:null});return}let offset=0,part=1;while(count-offset>29){groups.push({key:t+'__part'+part,baseKey:t,label:t+' '+part,count:20,offset,questionIds:ids.slice(offset,offset+20),questions:null});offset+=20;part++}const last=count-offset;if(last>0)groups.push({key:t+'__part'+part,baseKey:t,label:t+' '+part,count:last,offset,questionIds:ids.slice(offset,offset+last),questions:null})});return groups}
function getTopicGroups(){const selected=qLesson.value;return buildTopicGroups(questions.filter(q=>!selected||q.lesson===selected))}
async function updateTopics(){const lessonEl=document.getElementById('qLesson');const menu=document.getElementById('quizTopicMenu');const label=document.getElementById('topicPickerLabel');if(!lessonEl||!menu)return;const selected=lessonEl.value;if(!selected){window.qTopic={value:''};window.quizTopicGroups=[];menu.innerHTML='';if(label)label.textContent='Önce ders seçin';return}try{const data=await fetchSummary(selected);const groups=[];const seen={};buildSummaryTopicGroups(data.groups).forEach(g=>{if(seen[g.key])return;seen[g.key]=1;groups.push(g)});window.quizTopicGroups=groups;window.qTopic={value:''};menu.innerHTML=groups.map((g,i)=>{const status=statusHtmlFromIds(g.questionIds);return'<button type="button" class="topicPickerItem" onclick="selectQuizTopic('+i+')"><span class="topicPickerItemMain"><span class="topicNameLine"><b>'+escapeHtml(g.label)+'</b>'+status+'</span><small>'+g.count+' soru</small></span></button>'}).join('');if(label)label.textContent='Konu seçin'}catch(e){menu.innerHTML='<div class="muted">Konular yüklenemedi.</div>'}}
/* eski updateTopics kaldırıldı */
function startQuiz(providedQuestions,statusIds){wrongQuizMode=false;let arr=Array.isArray(providedQuestions)?providedQuestions.slice():[];if(!arr.length){const key=window.qTopic&&window.qTopic.value||'';if(key){const groups=window.subjectTopicGroups||window.quizTopicGroups||[];const g=groups.find(x=>x.key===key);arr=g&&Array.isArray(g.questions)?g.questions.slice():[]}else{const selected=window.qLesson&&window.qLesson.value||'';arr=questions.filter(q=>!selected||q.lesson===selected).slice()}}arr=arr.filter(q=>q&&q.question&&Array.isArray(q.options)&&q.options.length===5);const actualStatusIds=[...new Set(arr.map(q=>q&&q.id).filter(id=>id!=null).map(String))];arr.sort(()=>Math.random()-.5);quiz=arr;qi=0;score=0;answered=false;quizResults=[];if(!wrongQuizMode&&actualStatusIds.length)beginTestAttempt(actualStatusIds);else if(wrongQuizMode)window.activeTestStatusIds=null;renderQuestion()}
function renderQuestion(){if(!quiz.length){app.innerHTML=nav()+'<section class="card"><h2>Henüz soru yok.</h2></section>';return}if(qi>=quiz.length){const answeredCount=quizResults.length,correctCount=quizResults.filter(x=>x.ok).length,wrongCount=quizResults.filter(x=>!x.ok).length;const sheet=quiz.map((q,i)=>{const r=quizResults[i];const cls=r?(r.ok?'optikCorrect':'optikWrong'):'optikEmpty';const mark=r?(r.ok?'✓':'✕'):'•';return '<button type="button" class="optikCell '+cls+'" onclick="reviewOptikQuestion('+i+')" title="Soruyu görüntüle"><span class="optikNo">'+(i+1)+'</span><span class="optikMark">'+mark+'</span></button>'}).join('');app.innerHTML=nav()+'<section class="card center resultCard"><h2>🎉 Test Bitti</h2><div class="score">'+score+'/'+quiz.length+'</div><p>%'+Math.round(score/quiz.length*100)+' başarı</p><div class="optikSummary"><div><b>'+answeredCount+'</b><span>Çözülen</span></div><div class="optikCorrectBox"><b>'+correctCount+'</b><span>Doğru</span></div><div class="optikWrongBox"><b>'+wrongCount+'</b><span>Yanlış</span></div></div><h3 class="optikTitle">📝 Optik Sonuç</h3><div class="optikSheet">'+sheet+'</div><div class="quizFinishedActions"><button class="primary" onclick="quizSetup()">Yeni Test</button><button class="secondary" onclick="renderHome()">Ana Menü</button></div></section>';launchConfetti();return}answered=false;const q=quiz[qi];app.innerHTML=nav()+'<section class="card"><div class="topline"><span>'+escapeHtml(q.lesson)+' › '+escapeHtml(q.question_group||q.topic||'Genel')+'</span><div class="testActions"><button class="favoriteBtn" onclick="toggleFavorite()">'+(userFavorites.has(String(q.id))?'⭐ Favoriden Çıkar':'☆ Favoriye Ekle')+'</button><button class="finishQuizTop" onclick="finishQuiz()">🏁 Bitir</button></div></div><div class="progress"><i style="width:'+((qi)/quiz.length*100)+'%"></i></div><div class="questionLayout"><div><div class="questionTitleRow"><h2>'+escapeHtml(q.question)+'</h2></div><div class="options">'+q.options.map((x,i)=>'<button class="option" onclick="answer(\''+String.fromCharCode(65+i)+'\')"><b>'+String.fromCharCode(65+i)+')</b> '+escapeHtml(x)+'</button>').join('')+'<aside class="answerPanel" id="answerPanel"></aside></div></div><div class="quizBottomActions"><button id="nextBtn" class="nextTop" disabled>Sonraki Soru →</button></div></section>'}
function finishQuiz(){
  if(!quiz.length)return;
  const status=finishActiveTestAttempt();
  if(status==='complete')recordStreakDay();
  qi=quiz.length;
  renderQuestion();
}
function answer(letter){if(answered)return;answered=true;const q=quiz[qi],ok=letter===q.correct;quizResults[qi]={id:q.id,ok,selected:letter,correct:q.correct};if(ok)score++;else wrong.push(q);recordResult(q,ok);updateActiveTestAnswer(q.id);const buttons=document.querySelectorAll('.option');buttons.forEach((btn,i)=>{const l=String.fromCharCode(65+i);btn.disabled=true;if(l===q.correct)btn.classList.add('correctOption');if(l===letter&&!ok)btn.classList.add('wrongOption')});const panel=document.getElementById('answerPanel');panel.innerHTML='<div class="answerBox '+(ok?'answerOk':'answerWrong')+'"><h3>'+(ok?'✅ Doğru':'❌ Yanlış')+'</h3><span class="answerFinish"></span>'+(q.explanation?'<div class="explanation"><b>Açıklama</b><p>'+escapeHtml(q.explanation)+'</p></div>':'')+'</div>';const n=document.getElementById('nextBtn');n.disabled=false;n.onclick=()=>{if(qi===quiz.length-1){const status=finishActiveTestAttempt();if(status==='complete')recordStreakDay()}qi++;renderQuestion()};n.classList.add('ready')}
function reviewOptikQuestion(index){const r=quizResults[index];if(!quiz[index]||!r)return;qi=index;renderQuestion();answered=true;const q=quiz[index];document.querySelectorAll('.option').forEach((btn,i)=>{const l=String.fromCharCode(65+i);btn.disabled=true;if(l===q.correct)btn.classList.add('correctOption');if(l===r.selected&&!r.ok)btn.classList.add('wrongOption')});const panel=document.getElementById('answerPanel');if(panel){panel.innerHTML='<div class="answerBox '+(r.ok?'answerOk':'answerWrong')+'"><h3>'+(r.ok?'✅ Doğru':'❌ Yanlış')+'</h3><p class="reviewSelected">Verdiğin cevap: <b>'+escapeHtml(r.selected)+')</b> '+escapeHtml(q.options[letterIndex(r.selected)]||'')+'</p>'+(q.explanation?'<div class="explanation"><b>Açıklama</b><p>'+escapeHtml(q.explanation)+'</p></div>':'')+'<div class="reviewNavActions">'+(index>0?'<button type="button" class="secondary reviewPrevBtn">← Önceki Soru</button>':'')+(index<quiz.length-1?'<button type="button" class="primary reviewNextBtn">Sonraki Soru →</button>':'')+'</div><button type="button" class="secondary reviewBackBtn" onclick="qi=quiz.length;renderQuestion()">← Optiğe Dön</button></div>';const prev=panel.querySelector('.reviewPrevBtn'),next=panel.querySelector('.reviewNextBtn');if(prev&&index>0)prev.onclick=()=>reviewOptikQuestion(index-1);if(next&&index<quiz.length-1)next.onclick=()=>reviewOptikQuestion(index+1)}const n=document.getElementById('nextBtn');if(n)n.style.display='none'}function letterIndex(letter){return Math.max(0,String(letter||'A').charCodeAt(0)-65)}
function launchConfetti(){const d=document.createElement('div');d.id='confettiLayer';for(let i=0;i<70;i++){const p=document.createElement('i');p.className='confettiPiece';p.style.left=(Math.random()*100)+'%';p.style.animationDelay=(Math.random()*0.4)+'s';d.appendChild(p)}document.body.appendChild(d);setTimeout(()=>d.remove(),3000)}
function wrongLessonCatalog(){return [['🦷','Protetik Diş Tedavisi'],['🛠️','Restoratif Diş Tedavisi'],['〰️','Endodonti'],['🦷','Periodontoloji'],['😁','Ortodonti'],['👶','Pedodonti'],['🩺','Ağız, Diş ve Çene Cerrahisi'],['🩻','Ağız, Diş ve Çene Radyolojisi'],['🫀','Anatomi'],['🧠','Fizyoloji'],['🧪','Biyokimya'],['🦠','Mikrobiyoloji'],['🔬','Histoloji ve Embriyoloji'],['🧫','Patoloji'],['💊','Farmakoloji']]}
function showWrong(){if(!authUser){app.innerHTML=nav()+'<section class="card center"><h2>❌ Yanlışlarım</h2><p class="muted">Yanlışlarını kaydetmek için önce hesabına giriş yap.</p><button class="primary" onclick="navAccessMessage()">👤 Giriş Yap / Kayıt Ol</button></section>';return}const lessons=wrongLessonCatalog(),rows=lessons.map((x,i)=>{const count=userWrongQuestions.filter(q=>q.lesson===x[1]).length;return'<button type="button" class="wrongLessonRow" onclick="showWrongLesson('+i+')"><span><i>'+x[0]+'</i><b>'+escapeHtml(x[1])+'</b></span><em>'+count+' yanlış</em></button>'}).join('');app.innerHTML=nav()+'<section class="card"><h2>❌ Yanlışlarım</h2><p class="muted">Önce bir ders seç. Dersler sıralı ve sembolleriyle gösterilir.</p><div class="wrongLessonList">'+rows+'</div></section>'}
function showWrongLesson(index){if(!authUser){showWrong();return}const lesson=wrongLessonCatalog()[index];if(!lesson)return;const list=userWrongQuestions.filter(q=>q.lesson===lesson[1]);const items=list.map((q,i)=>'<div class="wrongItem"><div><b>'+escapeHtml(q.lesson)+' › '+escapeHtml(q.question_group||q.topic||'Genel')+'</b><p>'+escapeHtml(q.question)+'</p><small>Doğru cevap: <b>'+escapeHtml(q.correct)+'</b></small></div><button onclick="retryPersistentWrongByLesson('+index+','+i+')">Çöz</button></div>').join('');app.innerHTML=nav()+'<section class="card"><button class="backButton" onclick="showWrong()">← Derslere Dön</button><div class="wrongLessonHeader"><div><h2>'+lesson[0]+' '+escapeHtml(lesson[1])+'</h2><p class="muted">'+list.length+' yanlış soru</p></div><button class="primary wrongShuffleBtn" onclick="shuffleWrongLesson('+index+')">🔀 Karıştır ve Çöz</button></div><h3>❌ Yanlış Çözülmüş Sorular</h3><div class="wrongItemList">'+(items||'<p class="muted">Bu derste henüz yanlış soru yok.</p>')+'</div></section>'}
function shuffleWrongLesson(index){const lesson=wrongLessonCatalog()[index];if(!lesson)return;const list=userWrongQuestions.filter(q=>q.lesson===lesson[1]).slice().sort(()=>Math.random()-.5).slice(0,20);if(!list.length){showWrongLesson(index);return}wrongQuizMode=true;quiz=list.map(q=>({...q,options:[q.option_a,q.option_b,q.option_c,q.option_d,q.option_e]}));qi=0;score=0;wrong=[];renderQuestion()}
function retryPersistentWrongByLesson(index,i){const lesson=wrongLessonCatalog()[index];if(!lesson)return;const list=userWrongQuestions.filter(q=>q.lesson===lesson[1]);const q=list[i];if(!q)return;quiz=[{...q,options:[q.option_a,q.option_b,q.option_c,q.option_d,q.option_e]}];qi=0;score=0;wrong=[];renderQuestion()}
function retryWrong(i){quiz=[wrong[i]];qi=0;score=0;renderQuestion()}
function retryPersistentWrong(i){const q=userWrongQuestions[i];if(!q)return;quiz=[{...q,options:[q.option_a,q.option_b,q.option_c,q.option_d,q.option_e]}];qi=0;score=0;wrong=[];renderQuestion()}
function retryWrong(i){quiz=[wrong[i]];qi=0;score=0;renderQuestion()}
function retryPersistentWrong(i){const q=userWrongQuestions[i];if(!q)return;quiz=[{...q,options:[q.option_a,q.option_b,q.option_c,q.option_d,q.option_e]}];qi=0;score=0;wrong=[];renderQuestion()}
function toggleFavorite(){if(!authUser||!quiz[qi]){if(!authUser)openAccount();return}const q=quiz[qi],id=String(q.id),isFav=userFavorites.has(id);if(isFav){userFavorites.delete(id);userFavoriteQuestions=userFavoriteQuestions.filter(x=>String(x.id)!==id);fetch(API+'/user-data',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({question_id:q.id})}).catch(()=>{});}else{userFavorites.add(id);userFavoriteQuestions=[q,...userFavoriteQuestions.filter(x=>String(x.id)!==id)];fetch(API+'/user-data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'favorite',question_id:q.id})}).catch(()=>{});}const btn=document.querySelector('.testActions .favoriteBtn');if(btn)btn.textContent=userFavorites.has(id)?'⭐ Favoriden Çıkar':'☆ Favoriye Ekle'}
function showFavorites(){if(!authUser){app.innerHTML=nav()+'<section class="card center"><h2>⭐ Favori Sorular</h2><p class="muted">Favorilerini kaydetmek için önce hesabına giriş yap.</p><button class="primary" onclick="openAccount()">👤 Giriş Yap</button></section>';return}const list=userFavoriteQuestions;app.innerHTML=nav()+'<section class="card"><h2>⭐ Favori Sorular</h2>'+(list.length?list.map((q,i)=>'<div class="wrongItem"><div><b>'+escapeHtml(q.lesson)+' › '+escapeHtml(q.question_group||q.topic||'Genel')+'</b><p>'+escapeHtml(q.question)+'</p></div><button onclick="retryFavorite('+i+')">Çöz</button></div>').join(''):'<p class="muted">Henüz favori soru eklemedin.</p>')+'</section>'}
function retryFavorite(i){const q=userFavoriteQuestions[i];if(!q)return;quiz=[{...q,options:[q.option_a,q.option_b,q.option_c,q.option_d,q.option_e]}];qi=0;score=0;wrong=[];renderQuestion()}
function openAccount(){if(!authUser){window.location.href='/login.html?next=/';return}const s=getStats(),solved=new Set(history.map(x=>String(x.id))).size;app.innerHTML=nav()+'<section class="card"><button class="backButton" onclick="renderHome()">← Geri</button><h2>👤 '+escapeHtml(authUser.email||authUser.name||'Hesabım')+'</h2><div class="grid"><div class="stat"><b>'+solved+'</b><span>Farklı soru</span></div><div class="stat"><b>'+s.total+'</b><span>Toplam cevap</span></div><div class="stat"><b>%'+s.rate+'</b><span>Başarı</span></div></div><div class="accountActions"><button onclick="showWrong()">❌ Kalıcı Yanlışlar ('+userWrongQuestions.length+')</button><button onclick="showFavorites()">⭐ Favoriler ('+userFavoriteQuestions.length+')</button><button onclick="renderPersonalStats()">📊 Kişisel İstatistik</button><button class="mobileAccountFeedback" onclick="openFeedback()">💡 Öneri</button><button onclick="signOutUser()">🚪 Çıkış Yap</button></div></section>'}
function renderPersonalStats(){if(!authUser){openAccount();return}const by={};history.forEach(x=>{const k=x.lesson||'Diğer';(by[k]||(by[k]={total:0,correct:0})).total++;if(x.ok)by[k].correct++});const rows=Object.keys(by).map(k=>{const s=by[k];return'<div class="statsTopicRow"><span><b>'+escapeHtml(k)+'</b><small>'+s.total+' cevap · '+s.correct+' doğru</small></span><strong>%'+Math.round(s.correct/s.total*100)+'</strong></div>'}).join('');app.innerHTML=nav()+'<section class="card"><button class="backButton" onclick="openAccount()">← Hesabım</button><h2>📊 Kişisel İstatistik</h2><div class="statsTopicList">'+(rows||'<p class="muted">Henüz çözüm verisi yok.</p>')+'</div></section>'}
function openFeedback(){
  if(!authUser){location.href='/login?next=/';return}
  const old=document.getElementById('feedbackModal');if(old)old.remove();
  document.body.insertAdjacentHTML('beforeend','<div id="feedbackModal" class="feedbackOverlay" onclick="if(event.target===this)closeFeedback()"><div class="feedbackModal"><button class="feedbackClose" onclick="closeFeedback()">×</button><h2>💡 Önerin var mı?</h2><p class="muted">DUSCamp için önerini yazabilirsin.</p><textarea id="feedbackText" maxlength="1000" placeholder="Örneğin: İstatistiklerde şu özelliği görmek isterim..."></textarea><div id="feedbackMsg" class="feedbackMsg"></div><div class="feedbackActions"><button onclick="closeFeedback()">Vazgeç</button><button class="primary" onclick="submitFeedback()">Gönder</button></div></div></div>');
  setTimeout(()=>document.getElementById('feedbackText')?.focus(),50);
}
function closeFeedback(){const m=document.getElementById('feedbackModal');if(m)m.remove()}function closeLoginRequired(){const m=document.getElementById('loginRequiredModal');if(m)m.remove()}
async function submitFeedback(){
  const input=document.getElementById('feedbackText'),msg=document.getElementById('feedbackMsg');
  const value=(input?.value||'').trim();
  if(!value){if(msg)msg.textContent='Lütfen önerini yaz.';return}
  const btn=document.querySelector('#feedbackModal .feedbackActions .primary');if(btn)btn.disabled=true;
  try{
    const r=await fetch(API+'/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:value})});
    const data=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(data.error||'Öneri gönderilemedi.');
    if(msg)msg.innerHTML='✅ Önerin admin ekranına gönderildi.';
    if(input)input.disabled=true;
    setTimeout(closeFeedback,900);
  }catch(e){
    if(msg)msg.textContent='❌ '+e.message;
    if(btn)btn.disabled=false;
  }
}
async function signOutUser(){await window.hatchable.auth.signOut();authUser=null;userFavorites=new Set();userWrongQuestions=[];userFavoriteQuestions=[];history=[];localStorage.removeItem('dentatest_history');location.href='/'}
function stats(){const all=getStats(),clinical=['Protetik Diş Tedavisi','Restoratif Diş Tedavisi','Endodonti','Periodontoloji','Ortodonti','Pedodonti','Ağız, Diş ve Çene Cerrahisi','Ağız, Diş ve Çene Radyolojisi'],basic=['Diş Anatomisi','Anatomi','Fizyoloji','Biyokimya','Mikrobiyoloji','Histoloji ve Embriyoloji','Patoloji','Farmakoloji'],lessons=clinical.concat(basic);window.statsLessons=lessons;const icons=['🦷','🛠️','〰️','🦷','😁','👶','🩺','🩻','🦷','🫀','🧠','🧪','🦠','🔬','🧫','💊'],statsDisplayNames={'Ağız, Diş ve Çene Cerrahisi':'A. D. ve Çene Cerrahisi','Ağız, Diş ve Çene Radyolojisi':'A. D. ve Çene Radyolojisi'};const bankTotal=lessonCatalog.reduce((n,g)=>n+Number(g.count||0),0),solved=new Set(history.filter(x=>x.id!=null).map(x=>String(x.id))).size;const rows=lessons.map((l,i)=>{const total=lessonCatalog.filter(g=>g.lesson===l).reduce((n,g)=>n+Number(g.count||0),0);const lessonSolved=new Set(history.filter(x=>x.lesson===l&&x.id!=null).map(x=>String(x.id))).size;const displayName=statsDisplayNames[l]||l;return'<button class="statsLessonRow" onclick=statsLessonByIndex('+i+')><span><i>'+icons[i]+'</i><b>'+escapeHtml(displayName)+'</b><em>'+total+' soru · '+lessonSolved+' çözüldü</em></span></button>'}).join('');app.innerHTML=nav()+'<section class="card"><h2>📊 İstatistik</h2>'+streakCard()+'<button type="button" class="dailyTrackMobileBtn" onclick="dailyStats()">📅 Günlük Takip <span>→</span></button><div class="grid"><div class="stat"><b>'+bankTotal+'</b><span>Soru bankası</span></div><div class="stat"><b>'+solved+'</b><span>Toplam çözülen</span></div><div class="stat"><b>%'+all.rate+'</b><span>Genel başarı</span></div></div><h3>📚 Dersler — 16 Ders</h3><div class="statsLessonList">'+rows+'</div></section>'}
function streakStorageKey(){return 'dentatest_streak_v1'}
function loadStreak(){
  const key=streakStorageKey();
  try{
    const raw=authUser?localStorage.getItem(key):sessionStorage.getItem(key);
    const x=JSON.parse(raw||'null');
    return x&&typeof x==='object'?{streak:Number(x.streak||0),freeze:Number(x.freeze||0),lastDate:x.lastDate||'',warning:x.warning||''}:{streak:0,freeze:0,lastDate:'',warning:''}
  }catch(_){return{streak:0,freeze:0,lastDate:'',warning:''}}
}
function saveStreak(x){
  try{
    const key=streakStorageKey(),raw=JSON.stringify(x);
    if(authUser)localStorage.setItem(key,raw);else sessionStorage.setItem(key,raw)
  }catch(_){}
}
function dateOnly(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function dayDiff(a,b){return Math.round((new Date(b+'T00:00:00').getTime()-new Date(a+'T00:00:00').getTime())/86400000)}
function recordStreakDay(){
  const today=dateOnly(new Date()),s=loadStreak();
  if(s.lastDate===today)return s;
  let gap=s.lastDate?dayDiff(s.lastDate,today):0;
  s.warning='';
  if(!s.lastDate){
    s.streak=1
  }else if(gap===1){
    s.streak=Math.max(1,s.streak+1)
  }else if(gap===2&&s.freeze>0){
    s.freeze--;
    s.streak=Math.max(1,s.streak+1);
    s.warning='❄️ 1 günlük seri dondurma hakkın kullanıldı.'
  }else if(gap>=2){
    s.streak=1;
    s.awardedMilestones=0;
    s.warning='💔 Serin sıfırlandı. Bugün yeni bir seri başlattın.'
  }else{
    s.streak=Math.max(1,s.streak)
  }
  const earned=Math.floor(s.streak/10);
  const awarded=s.awardedMilestones||0;
  if(earned>awarded){
    s.freeze+=earned-awarded;
    s.awardedMilestones=earned;
    s.warning=(s.warning?s.warning+' ':'')+'🎁 10 günlük seri ödülü: +1 dondurma hakkı kazandın.'
  }
  s.lastDate=today;
  s.warning=s.warning||'';
  saveStreak(s);
  return s
}
function streakInfo(){
  const s=loadStreak(),today=dateOnly(new Date());
  let daysSince=s.lastDate?dayDiff(s.lastDate,today):0;
  if(s.lastDate&&daysSince>=2&&s.freeze===0)return {...s,previewReset:true};
  return {...s,previewReset:false}
}
function streakCard(){
  const s=streakInfo(),n=s.previewReset?0:s.streak,daysSince=s.lastDate?dayDiff(s.lastDate,dateOnly(new Date())):0;
  const freezeText=s.freeze>0?'❄️ '+s.freeze+' dondurma hakkı':'Dondurma hakkı yok';
  const milestone=n%10===0&&n>0?10:10-(n%10);
  let warning=s.warning||'';
  if(!warning&&daysSince===1)warning='⚠️ Dün test çözmedin. Bugün mutlaka 1 test çözerek serini koru.';
  if(!warning&&daysSince===2&&s.freeze>0)warning='❄️ Bugün 1 dondurma hakkın otomatik kullanılacak ve serin korunacak.';
  if(!warning&&daysSince>=2&&s.freeze===0)warning='💔 2 gün üst üste test çözülmedi. Bugün yeni seri başlayacak.';
  const warningHtml=warning?'<div class="streakWarning">'+escapeHtml(warning)+'</div>':'';
  return '<div class="streakCard"><div class="streakTop"><div><span class="streakLabel">🔥 Günlük Seri</span><div class="streakNumber">'+n+'</div><span class="streakUnit">gün</span></div><div class="streakFlame">🔥</div></div><div class="streakMeta"><span>'+freezeText+'</span><span>🎁 Sonraki ödül: '+milestone+' gün</span></div>'+warningHtml+'</div>'
}
function dailyStats(selectedYear){const now=new Date(),days=[];for(let i=6;i>=0;i--){const d=new Date(now);d.setHours(0,0,0,0);d.setDate(d.getDate()-i);days.push(d)}const dailyAttempts=loadDailyAttempts();const source=dailyAttempts.length?dailyAttempts:history;const answerTimes=source.map(x=>x&&x.answeredAt?new Date(x.answeredAt).getTime():NaN).filter(t=>!Number.isNaN(t));const counts=days.map(d=>{const start=d.getTime(),end=start+86400000;return answerTimes.filter(t=>t>=start&&t<end).length});const max=Math.max(1,...counts),labels=days.map(d=>String(d.getDate()).padStart(2,'0')+'.'+String(d.getMonth()+1).padStart(2,'0'));const bars=counts.map((n,i)=>'<div class="dailyBarCol"><span class="dailyBarValue">'+n+'</span><div class="dailyBarTrack"><i style="height:'+Math.max(4,Math.round(n/max*100))+'%"></i></div><b>'+labels[i]+'</b></div>').join('');const year=selectedYear||now.getFullYear(),monthNames=['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'],availableYears=[...new Set(answerTimes.map(t=>new Date(t).getFullYear()).concat([now.getFullYear()]))].sort((a,b)=>b-a),yearOptions=availableYears.map(y=>'<option value="'+y+'" '+(y===year?'selected':'')+'>'+y+'</option>').join(''),monthCounts=monthNames.map((_,m)=>answerTimes.filter(t=>{const d=new Date(t);return d.getFullYear()===year&&d.getMonth()===m}).length),monthMax=Math.max(1,...monthCounts),monthBars=monthCounts.map((n,m)=>'<div class="monthlyBarCol"><span class="monthlyBarValue">'+n+'</span><div class="monthlyBarTrack"><i style="height:'+Math.max(n?4:1,Math.round(n/monthMax*100))+'%"></i></div><b>'+monthNames[m]+'</b></div>').join('');app.innerHTML=nav()+'<section class="card">'+streakCard()+'<h2 class="dailyTitle">📅 Günlük Takip</h2><p class="muted">Son 7 gün — çözdüğün tüm soruların günlük sayısı. Aynı soruyu tekrar çözersen her çözüm ayrıca sayılır.</p><div class="dailyChart">'+bars+'</div><div class="dailySummary">Son 7 gün: <b>'+counts.reduce((a,b)=>a+b,0)+'</b> yeni soru</div><h2 class="monthlyTitle">📆 Aylık Takip</h2><div class="monthlyYearPicker"><label>Yıl<select onchange="dailyStats(Number(this.value))">'+yearOptions+'</select></label></div><p class="muted">'+year+' yılı — ay ay çözdüğün toplam soru sayısı.</p><div class="monthlyChart">'+monthBars+'</div><div class="dailySummary">'+year+' toplamı: <b>'+monthCounts.reduce((a,b)=>a+b,0)+'</b> soru</div></section>'}
function monthlyStats(){dailyStats()}
async function statsLessonByIndex(i){const lesson=(window.statsLessons||[])[i];if(!lesson)return;app.innerHTML=nav()+'<section class="card"><button class="backButton" onclick="stats()">← Derslere Dön</button><h2>📊 '+escapeHtml(lesson)+'</h2><div class="statsTopicList"><p class="muted">Konular hazırlanıyor…</p></div></section>';try{const data=await fetchSummary(lesson);const groups=[];const seen={};(data.groups||[]).forEach(g=>{const t=String(g.question_group||g.topic||'').trim();if(!t||t.toLocaleLowerCase('tr-TR')==='genel'||seen[t])return;seen[t]=1;groups.push({label:t,count:Number(g.count||0)})});const rows=groups.map(g=>{const attempts=history.filter(x=>x.lesson===lesson&&String(x.topic||'').trim()===g.label);const solved=new Set(attempts.filter(x=>x.id!=null).map(x=>String(x.id))).size;const rate=attempts.length?Math.round(attempts.filter(x=>x.ok).length/attempts.length*100):0;return'<div class="statsTopicRow"><span><b>📖 '+escapeHtml(g.label)+'</b><small>'+g.count+' soru · '+solved+' çözüldü</small></span><strong>%'+rate+'</strong></div>'}).join('');const list=app.querySelector('.statsTopicList');if(list)list.innerHTML=rows||'<p class="muted">Konu bulunamadı.</p>'}catch(e){const list=app.querySelector('.statsTopicList');if(list)list.innerHTML='<p class="muted">Konu özeti yüklenemedi.</p>'}}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
